// src/App.js - Updated version

import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [resumes, setResumes] = useState([]);
  const [jobDescription, setJobDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [jobTitle, setJobTitle] = useState('');

  // Configure axios base URL
  const API_BASE_URL = 'http://localhost:8000';
  axios.defaults.baseURL = API_BASE_URL;

  // Upload and parse resume
  const uploadResume = async (file) => {
    if (!file) {
      alert('Please select a file first');
      return;
    }

    const formData = new FormData();
    formData.append('file', file);

    setLoading(true);
    try {
      const response = await axios.post('/upload-resume/', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      // Add the resume data to the list
      const newResume = {
        id: response.data.resume_id || Date.now().toString(),
        name: response.data.data?.name || 'Unnamed Candidate',
        skills: response.data.data?.skills || [],
        experience: response.data.data?.experience || '',
        education: response.data.data?.education || '',
        filename: file.name,
        match_score: null,
        justification: null,
        matched_skills: [],
        missing_skills: []
      };

      setResumes([...resumes, newResume]);
      alert('Resume uploaded and parsed successfully!');
      setSelectedFile(null);
      // Reset file input
      document.getElementById('file-upload').value = '';
    } catch (error) {
      console.error('Upload error:', error);
      alert('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  // Match resume with job
  const matchResume = async (resumeId) => {
    if (!jobDescription.trim()) {
      alert('Please add a job description first');
      return;
    }

    setLoading(true);
    try {
      // First, save the job description
      const jobResponse = await axios.post('/save-job/', {
        title: jobTitle || 'Untitled Position',
        description: jobDescription,
        requirements: jobDescription
      });

      const jobId = jobResponse.data.job_id;

      // Then match the resume
      const matchResponse = await axios.post('/match-resume/', {
        resume_id: resumeId,
        job_id: jobId
      });

      // Update the resume with match score
      setResumes(resumes.map(resume => 
        resume.id === resumeId 
          ? { 
              ...resume, 
              match_score: matchResponse.data.match_score,
              justification: matchResponse.data.justification,
              matched_skills: matchResponse.data.matched_skills || [],
              missing_skills: matchResponse.data.missing_skills || []
            }
          : resume
      ));

      alert('Match calculated successfully!');

    } catch (error) {
      console.error('Match error:', error);
      alert('Failed to match resume: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  // Get shortlisted candidates - FIXED VERSION
  const getShortlisted = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/shortlisted/?min_score=7');
      console.log('Shortlisted response:', response.data); // Debug log

      // Extract candidates from the response
      let candidates = [];
      if (response.data && response.data.candidates) {
        // If response has candidates array
        candidates = response.data.candidates;
      } else if (Array.isArray(response.data)) {
        // If response is directly an array
        candidates = response.data;
      } else if (response.data && response.data.resumes) {
        // If response has resumes array
        candidates = response.data.resumes;
      } else {
        // If response is something else, try to handle it
        console.warn('Unexpected response format:', response.data);
        candidates = [];
      }

      // Map candidates to match your frontend format
      const formattedCandidates = candidates.map(candidate => ({
        id: candidate.id || candidate._id || Date.now().toString(),
        name: candidate.name || 'Unnamed Candidate',
        skills: candidate.skills || [],
        experience: candidate.experience || '',
        education: candidate.education || '',
        match_score: candidate.match_score || 0,
        justification: candidate.justification || 'No justification provided',
        matched_skills: candidate.matched_skills || [],
        missing_skills: candidate.missing_skills || [],
        filename: candidate.filename || ''
      }));

      setResumes(formattedCandidates);

      if (formattedCandidates.length === 0) {
        alert('No shortlisted candidates found (score >= 7)');
      } else {
        alert(`Found ${formattedCandidates.length} shortlisted candidates!`);
      }

    } catch (error) {
      console.error('Error fetching shortlisted:', error);
      alert('Failed to fetch shortlisted candidates: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  // Get all resumes (optional - to refresh the list)
  const getAllResumes = async () => {
    setLoading(true);
    try {
      const response = await axios.get('/resumes/');
      console.log('All resumes:', response.data);

      let resumes = [];
      if (response.data && response.data.resumes) {
        resumes = response.data.resumes;
      } else if (Array.isArray(response.data)) {
        resumes = response.data;
      }

      const formattedResumes = resumes.map(resume => ({
        id: resume.id || resume._id || Date.now().toString(),
        name: resume.name || 'Unnamed Candidate',
        skills: resume.skills || [],
        experience: resume.experience || '',
        education: resume.education || '',
        match_score: resume.match_score || null,
        justification: resume.justification || null,
        matched_skills: resume.matched_skills || [],
        missing_skills: resume.missing_skills || [],
        filename: resume.filename || ''
      }));

      setResumes(formattedResumes);
    } catch (error) {
      console.error('Error fetching resumes:', error);
      alert('Failed to fetch resumes');
    } finally {
      setLoading(false);
    }
  };

  // Handle file selection
  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const validTypes = ['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
      if (!validTypes.includes(file.type)) {
        alert('Please upload a PDF or DOCX file');
        return;
      }
      setSelectedFile(file);
    }
  };

  // Handle file upload button click
  const handleUpload = () => {
    if (selectedFile) {
      uploadResume(selectedFile);
    } else {
      alert('Please select a file');
    }
  };

  // Candidate Card Component
  const CandidateCard = ({ resume }) => {
    // Debug log to see what each resume contains
    console.log('Rendering resume:', resume);

    return (
      <div className="candidate-card">
        <h3>{resume.name || `Candidate ${resume.id}`}</h3>
        {resume.filename && (
          <div className="filename">
            <small>📄 {resume.filename}</small>
          </div>
        )}
        {resume.match_score !== null && resume.match_score !== undefined && (
          <div className="match-score">
            <span className="score">Match Score: {resume.match_score}/10</span>
          </div>
        )}
        {resume.justification && (
          <div className="justification">
            <strong>Justification:</strong> {resume.justification}
          </div>
        )}
        {resume.skills && resume.skills.length > 0 && (
          <div className="skills">
            <strong>Skills:</strong> {resume.skills.join(', ')}
          </div>
        )}
        {resume.experience && (
          <div className="experience">
            <strong>Experience:</strong> {resume.experience}
          </div>
        )}
        {resume.education && (
          <div className="education">
            <strong>Education:</strong> {resume.education}
          </div>
        )}
        {resume.matched_skills && resume.matched_skills.length > 0 && (
          <div className="matched-skills">
            <strong style={{ color: 'green' }}>✅ Matched Skills:</strong> {resume.matched_skills.join(', ')}
          </div>
        )}
        {resume.missing_skills && resume.missing_skills.length > 0 && (
          <div className="missing-skills">
            <strong style={{ color: 'red' }}>❌ Missing Skills:</strong> {resume.missing_skills.join(', ')}
          </div>
        )}
        {(!resume.match_score || resume.match_score === null) && (
          <button 
            onClick={() => matchResume(resume.id)}
            className="match-btn"
            disabled={loading}
          >
            {loading ? 'Processing...' : 'Match with Job'}
          </button>
        )}
      </div>
    );
  };

  return (
    <div className="App">
      <header className="app-header">
        <h1>🤖 Smart Resume Screener</h1>
        <p>Upload resumes and match them with job descriptions using AI</p>
      </header>

      <div className="container">
        <div className="left-panel">
          {/* Job Description Input */}
          <div className="section">
            <h2>📋 Job Description</h2>
            <input
              type="text"
              placeholder="Job Title"
              value={jobTitle}
              onChange={(e) => setJobTitle(e.target.value)}
              className="job-title-input"
            />
            <textarea
              placeholder="Paste job description here..."
              value={jobDescription}
              onChange={(e) => setJobDescription(e.target.value)}
              rows="6"
              className="job-description-input"
            />
            <button 
              onClick={() => {
                if (jobDescription.trim()) {
                  alert('Job description saved! You can now match resumes.');
                } else {
                  alert('Please paste a job description first.');
                }
              }} 
              className="save-job-btn"
            >
              Save Job Description
            </button>
          </div>

          {/* Resume Upload */}
          <div className="section">
            <h2>📄 Upload Resume</h2>
            <div className="upload-area">
              <input
                type="file"
                accept=".pdf,.docx"
                onChange={handleFileChange}
                className="file-input"
                id="file-upload"
              />
              <label htmlFor="file-upload" className="file-label">
                {selectedFile ? selectedFile.name : 'Choose a PDF or DOCX file'}
              </label>
              <button 
                onClick={handleUpload}
                className="upload-btn"
                disabled={loading || !selectedFile}
              >
                {loading ? 'Uploading...' : 'Upload Resume'}
              </button>
            </div>
          </div>

          {/* Actions */}
          <div className="section">
            <button 
              onClick={getShortlisted} 
              className="shortlist-btn" 
              disabled={loading}
            >
              {loading ? 'Loading...' : '🏆 Get Shortlisted Candidates'}
            </button>
            <button 
              onClick={getAllResumes} 
              className="refresh-btn" 
              disabled={loading}
              style={{ marginTop: '10px', width: '100%' }}
            >
              🔄 Refresh All Resumes
            </button>
          </div>
        </div>

        <div className="right-panel">
          <h2>📊 Candidates ({resumes.length})</h2>
          <div className="candidates-list">
            {resumes.length === 0 ? (
              <p className="no-candidates">No resumes uploaded yet. Upload a resume to get started!</p>
            ) : (
              resumes.map((resume, index) => {
                // Ensure each resume has a unique key
                const key = resume.id || resume._id || `resume-${index}`;
                return <CandidateCard key={key} resume={resume} />;
              })
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
